from mechanism_design_context import add
add('ragtruth',12,'N','FACT','T','P','misreads_text','consistent','unsupported_target_inference',[( 'does not contain any information regarding the price','target','It was a good Japanese restaurant with reasonable prices','Review expressly supports price characterization.')],'False denial of supplied price evidence. It also approves listed hours without acknowledging newer permanent-closure review; core claimed error is demonstrably source-supported.')
add('ragtruth',13,'N','FACT','T','N','unsupported_inference','consistent','unsupported_target_inference,uncertain',[( 'strictly based on the provided passages','target','rising sea levels, more frequent natural disasters, and air pollution','These consequence details are not stated in target source.'),('climate change, as stated in the passages','target','measures the environmental impact of your lifestyle','Source measures impacts but does not explicitly state these consequences.')],'Overstates source support. Some external facts may be correct, which the rubric exempts; no claim here that absent source wording alone proves hallucination.')
add('ragtruth',14,'N','FACT','T','N','misreads_text','consistent','unsupported_target_inference',[( '100 passengers and 5 crew','target',"Of the ship's 2,117 passengers, 95 have suffered",'Rationale repeats response\'s incorrect passenger count.'),('accurately reflects the source content','target','The illness has also affected five members','100 is total affected, not passengers before adding crew.')],'Fails basic total/subgroup distinction, affirming 105 affected where source specifies 100.')
add('ragtruth',15,'N','FACT','T','N','misreads_text','consistent','unsupported_target_inference',[( 'categories, hours, attributes (including parking, outdoor seating, WiFi, takeout, and group-friendly)','target','The restaurant offers both indoor and outdoor seating, and parking is readily available.','Response mentions only some attributes and no hours/WiFi/takeout/group-friendly claim.')],'Core positive review summary is supported, but rationale hallucinates coverage of several fields not present in response; some-reviewers salad statement also generalizes one review. No explicit neighbour use.')
